<template><view class="page"><view class="fixed"><u-search v-model="keyword" placeholder="客户 / 手机号 / 卡号 / 操作人" :showAction="false" bgColor="#fff" @search="reload" @clear="reload"/><view class="tabs"><text :class="{active:status===''}" @click="status='';reload()">全部</text><text :class="{active:status==='success'}" @click="status='success';reload()">核销成功</text><text :class="{active:status==='reversed'}" @click="status='reversed';reload()">已冲正</text></view></view><z-paging ref="paging" v-model="rows" :fixed="true" :paging-style="pagingStyle" @query="query"><template #empty><u-empty text="暂无核销记录" mode="list"/></template><view class="list"><view v-for="row in rows" :key="row.id" class="record"><view class="head"><view><strong>{{row.item_name}}</strong><text>{{row.holder_name}} · {{mask(row.holder_mobile)}}</text></view><u-tag :text="row.status==='success'?'核销成功':'已冲正'" :type="row.status==='success'?'success':'info'" plain size="mini"/></view><view class="amount"><text>次数 {{row.before_remaining}} → {{row.after_remaining}}</text><strong>确认收入 ¥{{money(row.recognized_amount)}}</strong></view><view class="meta"><text>{{row.operator_name}} · {{time(row.occurred_at)}}</text><text>{{row.redeem_no}}</text></view><u-button v-if="row.status==='success'" type="warning" plain size="small" text="冲正并恢复次数" @click="reverse(row)"/></view></view></z-paging></view></template>
<script setup lang="ts">import{computed,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{getCardRedemptions,memberCardRequestId,reverseCardRedemption}from'../../api';const keyword=ref(''),status=ref(''),rows=ref<any[]>([]),paging=ref<any>(),pagingStyle=computed(()=>({top:'176rpx',bottom:'0'})),reload=()=>paging.value?.reload();const query=async(page:number,limit:number)=>{try{const r:any=await getCardRedemptions({keyword:keyword.value,status:status.value,page,limit});paging.value?.complete(r?.data?.data||[])}catch{paging.value?.complete(false)}};const money=(v:any)=>Number(v||0).toFixed(2),mask=(v:string)=>/^\d{11}$/.test(v||'')?`${v.slice(0,3)}****${v.slice(-4)}`:(v||'—'),time=(v:any)=>v?new Date(Number(v)*1000).toLocaleString('zh-CN',{hour12:false}).slice(0,16):'—';const reverse=async(row:any)=>{const modal=await uni.showModal({title:'核销冲正',editable:true,placeholderText:'必须填写冲正原因',content:'冲正会恢复本次扣减的次数，原记录永久保留。',confirmText:'确认冲正'});if(!modal.confirm)return;const reason=String((modal as any).content||'').trim();if(!reason)return uni.showToast({title:'必须填写冲正原因',icon:'none'});await reverseCardRedemption(row.id,{request_id:memberCardRequestId('reverse'),reason});uni.showToast({title:'冲正成功',icon:'success'});reload()};onShow(reload)</script>
<style scoped>.page{min-height:100vh;background:#f3f4f6}.fixed{position:fixed;z-index:10;top:0;right:0;left:0;padding:18rpx 24rpx 0;background:#f3f4f6}.tabs{display:flex;height:80rpx;gap:15rpx;align-items:center}.tabs text{padding:12rpx 24rpx;border-radius:24rpx;background:#fff;color:#64748b}.tabs text.active{background:#3b6ef5;color:#fff}.list{padding:18rpx 24rpx}.record{margin-bottom:18rpx;padding:24rpx;border:1rpx solid #e5eaf1;border-radius:18rpx;background:#fff}.head,.amount,.meta{display:flex;align-items:center;justify-content:space-between;gap:14rpx}.head>view{display:flex;flex-direction:column;gap:7rpx}.head text,.meta{color:#64748b;font-size:21rpx}.amount{margin:19rpx 0;padding:17rpx 0;border-top:1rpx solid #eef2f7;border-bottom:1rpx solid #eef2f7}.amount strong{color:#16a34a}.meta{margin-bottom:16rpx}</style>
